import json
import re
import sys

def parse_script(text):
    nodes = []
    edges = []

    # Use findall to get all blocks, ensuring [NodeID] is at the start of a line
    blocks = re.findall(r'^\[(.*?)\](.*?)(?=^\[|$)', text, re.DOTALL | re.MULTILINE)

    node_map = {}

    for node_id, content in blocks:
        node_id = node_id.strip()
        content = content.strip()

        node = {
            "id": node_id,
            "text": "",
            "speaker": "",
            "type": ""
        }

        # Check for choices: Number. Text -> Target
        # Note: target can contain underscores or numbers, \w+ is usually fine but let's be safe
        choice_matches = re.findall(r'^\d+\.\s+(.*?)\s*->\s*(\w+)$', content, re.MULTILINE)

        if choice_matches:
            node["type"] = "choice"
            for opt_text, target in choice_matches:
                edges.append({
                    "from": node_id,
                    "to": target,
                    "text": opt_text.strip()
                })
        else:
            # Check for line: Speaker: Text -> Target
            line_match = re.search(r'^([^:]+):\s+(.*?)\s*->\s*(\w+)$', content, re.MULTILINE | re.DOTALL)
            if line_match:
                node["type"] = "line"
                node["speaker"] = line_match.group(1).strip()
                node["text"] = line_match.group(2).strip().replace('\n', ' ')
                target = line_match.group(3).strip()
                edges.append({
                    "from": node_id,
                    "to": target,
                    "text": ""
                })
            else:
                node["type"] = "line"

        nodes.append(node)
        node_map[node_id] = node

    # Add "End" node if it's targeted but not defined
    targets = set(edge["to"] for edge in edges)
    if "End" in targets and "End" not in node_map:
        nodes.append({
            "id": "End",
            "text": "",
            "speaker": "",
            "type": "line"
        })

    return {"nodes": nodes, "edges": edges}

def generate_dot(graph):
    dot = ["digraph G {"]
    dot.append("  node [fontname=\"Arial\", shape=box];")

    for node in graph["nodes"]:
        node_id = node["id"]
        ntype = node["type"]
        speaker = node["speaker"]
        text = node["text"]

        if ntype == "choice":
            shape = "diamond"
            label = node_id
        else:
            shape = "box"
            if speaker:
                label = f"{speaker}: {text}"
            else:
                label = text if text else node_id

        label = label.replace('"', '\\"')
        dot.append(f'  "{node_id}" [label="{label}", shape={shape}];')

    for edge in graph["edges"]:
        u = edge["from"]
        v = edge["to"]
        t = edge["text"].replace('"', '\\"')
        if t:
            dot.append(f'  "{u}" -> "{v}" [label="{t}"];')
        else:
            dot.append(f'  "{u}" -> "{v}";')

    dot.append("}")
    return "\n".join(dot)

if __name__ == "__main__":
    with open("/app/script.txt", "r") as f:
        content = f.read()

    graph = parse_script(content)

    with open("/app/dialogue.json", "w") as f:
        json.dump(graph, f, indent=2)

    dot_content = generate_dot(graph)
    with open("/app/dialogue.dot", "w") as f:
        f.write(dot_content)

